SET NAMES utf8mb4;
DELIMITER $$

DROP PROCEDURE IF EXISTS `LTP_sp_direct_inbox`$$
CREATE OR REPLACE PROCEDURE `LTP_sp_direct_inbox`(IN p_actor BIGINT UNSIGNED)
BEGIN
 SELECT c.id,u.full_name AS other_name,
 (SELECT body FROM direct_messages WHERE conversation_id=c.id ORDER BY id DESC LIMIT 1) AS last_body,
 (SELECT COUNT(*) FROM direct_messages WHERE conversation_id=c.id AND sender_id<>p_actor AND read_at IS NULL) AS unread_count
 FROM direct_conversations c JOIN users u ON u.id=IF(c.member_a=p_actor,c.member_b,c.member_a)
 JOIN users me ON me.id=p_actor AND me.status='active' AND me.deleted_at IS NULL
 WHERE p_actor IN(c.member_a,c.member_b)
 ORDER BY COALESCE((SELECT MAX(created_at) FROM direct_messages WHERE conversation_id=c.id),c.created_at) DESC LIMIT 200;
END$$

DROP PROCEDURE IF EXISTS `LTP_sp_direct_open`$$
CREATE OR REPLACE PROCEDURE `LTP_sp_direct_open`(IN p_actor BIGINT UNSIGNED,IN p_listing BIGINT UNSIGNED)
BEGIN
 DECLARE v_other BIGINT UNSIGNED;
 IF NOT EXISTS(SELECT 1 FROM users WHERE id=p_actor AND status='active' AND deleted_at IS NULL) THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Vui lòng đăng nhập lại.';
 END IF;
 IF p_listing>0 THEN
  SELECT l.host_id INTO v_other FROM listings l JOIN users u ON u.id=l.host_id
  WHERE l.id=p_listing AND l.moderation_status='approved' AND l.is_visible=1 AND COALESCE(l.admin_hidden,0)=0 AND l.deleted_at IS NULL
  AND u.status='active' AND u.deleted_at IS NULL AND EXISTS(SELECT 1 FROM user_roles WHERE user_id=l.host_id AND role='host');
 ELSE
  SELECT MIN(u.id) INTO v_other FROM users u JOIN user_roles r ON r.user_id=u.id
  WHERE r.role='admin' AND u.id<>p_actor AND u.status='active' AND u.deleted_at IS NULL;
 END IF;
 IF v_other IS NULL OR v_other=p_actor THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Không có người nhận phù hợp.'; END IF;
 INSERT INTO direct_conversations(member_a,member_b) VALUES(LEAST(p_actor,v_other),GREATEST(p_actor,v_other))
 ON DUPLICATE KEY UPDATE id=LAST_INSERT_ID(id);
 SELECT id FROM direct_conversations WHERE member_a=LEAST(p_actor,v_other) AND member_b=GREATEST(p_actor,v_other);
END$$

DROP PROCEDURE IF EXISTS `LTP_sp_direct_send`$$
CREATE OR REPLACE PROCEDURE `LTP_sp_direct_send`(IN p_chat BIGINT UNSIGNED,IN p_actor BIGINT UNSIGNED,IN p_body TEXT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci)
BEGIN
 DECLARE v_id BIGINT UNSIGNED;
 DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN ROLLBACK; RESIGNAL; END;
 START TRANSACTION;
 SELECT id INTO v_id FROM direct_conversations WHERE id=p_chat AND p_actor IN(member_a,member_b) FOR UPDATE;
 IF v_id IS NULL OR EXISTS(SELECT 1 FROM direct_conversations c JOIN users u ON u.id IN(c.member_a,c.member_b) WHERE c.id=p_chat AND (u.status<>'active' OR u.deleted_at IS NOT NULL)) THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Không thể gửi tin nhắn tới cuộc trò chuyện này.';
 END IF;
 IF CHAR_LENGTH(TRIM(p_body))<1 OR CHAR_LENGTH(p_body)>2000 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Tin nhắn cần từ 1 đến 2000 ký tự.'; END IF;
 IF EXISTS(SELECT 1 FROM direct_messages WHERE sender_id=p_actor AND conversation_id=p_chat AND created_at>NOW(6)-INTERVAL 2 SECOND) THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Vui lòng chờ một chút trước khi gửi tiếp.';
 END IF;
 INSERT INTO direct_messages(conversation_id,sender_id,body) VALUES(p_chat,p_actor,p_body);
 COMMIT;
END$$

DROP PROCEDURE IF EXISTS `LTP_sp_direct_state`$$
CREATE OR REPLACE PROCEDURE `LTP_sp_direct_state`(IN p_chat BIGINT UNSIGNED,IN p_actor BIGINT UNSIGNED)
BEGIN
 SELECT c.id,u.full_name AS other_name,'guest' AS my_role,'pending' AS status,
 (u.status='active' AND u.deleted_at IS NULL) AS can_send, (u.deleted_at IS NOT NULL) AS other_deleted
 FROM direct_conversations c JOIN users u ON u.id=IF(c.member_a=p_actor,c.member_b,c.member_a)
 JOIN users me ON me.id=p_actor AND me.status='active' AND me.deleted_at IS NULL
 WHERE c.id=p_chat AND p_actor IN(c.member_a,c.member_b);
END$$

DROP PROCEDURE IF EXISTS `LTP_sp_direct_thread`$$
CREATE OR REPLACE PROCEDURE `LTP_sp_direct_thread`(IN p_chat BIGINT UNSIGNED,IN p_actor BIGINT UNSIGNED)
BEGIN
 IF NOT EXISTS(SELECT 1 FROM direct_conversations c JOIN users u ON u.id=p_actor AND u.status='active' AND u.deleted_at IS NULL WHERE c.id=p_chat AND p_actor IN(c.member_a,c.member_b)) THEN
  SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Không tìm thấy cuộc trò chuyện.';
 END IF;
 UPDATE direct_messages SET read_at=COALESCE(read_at,NOW(6)) WHERE conversation_id=p_chat AND sender_id<>p_actor;
 SELECT recent.*,u.full_name AS sender_name,(recent.sender_id=p_actor) AS is_mine,0 AS is_hidden
 FROM (SELECT * FROM direct_messages WHERE conversation_id=p_chat ORDER BY id DESC LIMIT 500) recent
 JOIN users u ON u.id=recent.sender_id ORDER BY recent.id;
END$$

DROP PROCEDURE IF EXISTS `NTK_sp_admin_host_request_decide`$$
CREATE OR REPLACE PROCEDURE `NTK_sp_admin_host_request_decide`(IN p_admin BIGINT UNSIGNED,IN p_user BIGINT UNSIGNED,IN p_decision VARCHAR(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,IN p_reason VARCHAR(1000) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci,IN p_allow_debug BOOLEAN)
BEGIN
 DECLARE v_user BIGINT UNSIGNED;
 DECLARE v_debug BOOLEAN;
 DECLARE v_own BOOLEAN DEFAULT FALSE;
 DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN IF @@in_transaction THEN IF v_own THEN ROLLBACK; ELSE ROLLBACK TO SAVEPOINT host_decide; RELEASE SAVEPOINT host_decide; END IF; END IF; RESIGNAL; END;
 SET v_own=(@@in_transaction=0);
 IF v_own THEN START TRANSACTION; ELSE SAVEPOINT host_decide; END IF;
 CALL NTK_sp_admin_assert_role(p_admin);
 IF p_admin=p_user THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='You cannot review your own host request.'; END IF;
 IF p_decision NOT IN ('approved','rejected') OR p_decision IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Invalid decision.'; END IF;
 IF p_decision='rejected' AND TRIM(COALESCE(p_reason,''))='' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='A rejection reason is required.'; END IF;
 SELECT id INTO v_user FROM users WHERE id=p_user AND status='active' AND deleted_at IS NULL FOR UPDATE;
 IF v_user IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Account unavailable.'; END IF;
 IF NOT EXISTS(SELECT 1 FROM host_requests WHERE user_id=p_user AND status='pending') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Request is no longer pending.'; END IF;
 SELECT is_debug INTO v_debug FROM host_requests WHERE user_id=p_user FOR UPDATE;
 IF p_decision='approved' THEN
 IF COALESCE((SELECT action FROM admin_audit_logs WHERE entity_type='user' AND entity_id=p_user AND action IN ('remove_host_role','grant_host_role') ORDER BY id DESC LIMIT 1),'')='remove_host_role' THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Host role was revoked. Restore access through user management first.'; END IF;
 IF NOT EXISTS(SELECT 1 FROM host_requests r JOIN users u ON u.id=r.user_id WHERE r.user_id=p_user AND r.email=u.email AND r.phone=u.phone) THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Profile changed. Reject this request and ask the user to reapply.'; END IF;
 IF v_debug AND NOT p_allow_debug THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Debug requests can only be approved locally with debug verification enabled.'; END IF;
 IF NOT v_debug AND NOT EXISTS(SELECT 1 FROM users u JOIN contact_verifications c ON c.user_id=u.id WHERE u.id=p_user AND c.email=u.email AND c.email_verified_at IS NOT NULL AND c.verified_phone=u.phone AND c.phone_verified_at IS NOT NULL AND EXISTS(SELECT 1 FROM identity_verifications v WHERE v.user_id=u.id AND v.status='approved' AND REGEXP_REPLACE(u.phone,'[[:space:].()-]','') IN (v.phone,CONCAT('+84',SUBSTRING(v.phone,2)),CONCAT('84',SUBSTRING(v.phone,2))))) THEN
 SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Current contact and identity verification is required.'; END IF;
 END IF;
 UPDATE host_requests SET status=p_decision,reason=TRIM(COALESCE(p_reason,'')),reviewed_by=p_admin,reviewed_at=NOW(6) WHERE user_id=p_user;
 IF p_decision='approved' THEN
 INSERT IGNORE INTO user_roles(user_id,role,granted_at) VALUES(p_user,'host',NOW(6));
 END IF;
 INSERT INTO admin_audit_logs(admin_id,action,entity_type,entity_id,change_summary,created_at) VALUES(p_admin,IF(p_decision='approved','grant_host_role','reject_host_request'),'user',p_user,JSON_OBJECT('reason',p_reason,'debug',v_debug),NOW(6));
 IF v_own THEN COMMIT; ELSE RELEASE SAVEPOINT host_decide; END IF;
END$$

DROP PROCEDURE IF EXISTS `NTK_sp_admin_host_requests`$$
CREATE OR REPLACE PROCEDURE `NTK_sp_admin_host_requests`(IN p_admin BIGINT UNSIGNED)
BEGIN
 CALL NTK_sp_admin_assert_role(p_admin);
 SELECT r.*,u.full_name,u.status account_status FROM host_requests r JOIN users u ON u.id=r.user_id ORDER BY r.status='pending' DESC,r.created_at DESC;
END$$

DROP PROCEDURE IF EXISTS `NTK_sp_host_request_status`$$
CREATE OR REPLACE PROCEDURE `NTK_sp_host_request_status`(IN p_user BIGINT UNSIGNED)
BEGIN
 SELECT * FROM host_requests WHERE user_id=p_user;
END$$

DROP PROCEDURE IF EXISTS `NTK_sp_host_request_submit`$$
CREATE OR REPLACE PROCEDURE `NTK_sp_host_request_submit`(IN p_user BIGINT UNSIGNED, IN p_debug BOOLEAN)
BEGIN
 DECLARE v_user BIGINT UNSIGNED;
 DECLARE v_own BOOLEAN DEFAULT FALSE;
 DECLARE EXIT HANDLER FOR SQLEXCEPTION BEGIN IF @@in_transaction THEN IF v_own THEN ROLLBACK; ELSE ROLLBACK TO SAVEPOINT host_submit; RELEASE SAVEPOINT host_submit; END IF; END IF; RESIGNAL; END;
 SET v_own=(@@in_transaction=0);
 IF v_own THEN START TRANSACTION; ELSE SAVEPOINT host_submit; END IF;
 SELECT id INTO v_user FROM users WHERE id=p_user AND status='active' AND deleted_at IS NULL FOR UPDATE;
 IF v_user IS NULL THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Account unavailable.'; END IF;
 IF EXISTS(SELECT 1 FROM user_roles WHERE user_id=p_user AND role='host') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Already a host.'; END IF;
 IF COALESCE((SELECT action FROM admin_audit_logs WHERE entity_type='user' AND entity_id=p_user AND action IN ('remove_host_role','grant_host_role') ORDER BY id DESC LIMIT 1),'')='remove_host_role' THEN
 SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Host access was removed by an admin. Contact an admin.'; END IF;
 IF EXISTS(SELECT 1 FROM host_requests WHERE user_id=p_user AND status='pending') THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='Your host request is already pending.'; END IF;
 INSERT INTO host_requests(user_id,email,phone,is_debug) SELECT id,email,phone,p_debug FROM users WHERE id=p_user
 ON DUPLICATE KEY UPDATE status='pending',email=VALUES(email),phone=VALUES(phone),is_debug=VALUES(is_debug),reason='',reviewed_by=NULL,created_at=NOW(6),reviewed_at=NULL;
 IF v_own THEN COMMIT; ELSE RELEASE SAVEPOINT host_submit; END IF;
END$$

DROP PROCEDURE IF EXISTS `DST_sp_facebook_identity_find`$$
